def safe_transfer(accounts, from_acc, to_acc, amount):
    logs = []
    transfers = {'pending': amount}
    try:
        if accounts.get(from_acc, 0) < 0 or accounts.get(to_acc, 0) < 0:
            raise ValueError('Invalid balance')
        accounts[from_acc] = accounts.get(from_acc, 0) - amount
        accounts[to_acc] = accounts.get(to_acc, 0) + amount
    except ValueError as e:
        logs.append(f'Error: {e}')
    else:
        logs.append('Transfer successful.')
    finally:
        transfers['pending'] = 0
        logs.append('Transaction finalized.')
    return logs

