class DataCorruptionError(Exception):
    pass

def validate_and_save(payload):
    lock_acquired = False
    try:
        if not isinstance(payload, dict):
            raise DataCorruptionError('Payload must be a dict')
        if not payload.get('valid', False):
            raise DataCorruptionError('Record invalid')
        lock_acquired = True
    except DataCorruptionError as e:
        print('Validation error:', e)
        raise
    else:
        print('Saved valid record.')
    finally:
        print('Lock released.')
